//       寫進對照表，供教練查 user ID 是誰。不用每新增一個LINE帳號都重講一次。
// 事件：message:received
// 軍師建立 2026-07-24 深夜（bni_tainan 專用），2026-07-26 教練指示泛化到全部LINE帳號

const fs = require('fs');
const path = require('path');
const https = require('https');

const HOME = process.env.HOME;
const STATE_DIR = path.join(HOME, '.openclaw', 'workspace', 'state');
const CREDENTIALS_DIR = path.join(HOME, '.openclaw', 'credentials');
const AGENTS_DIR = path.join(HOME, '.openclaw', 'agents');

function mapFilePath(accountId) {
  return path.join(STATE_DIR, `${accountId}_line_id_map.json`);
}

function tokenFilePath(accountId) {
  return path.join(CREDENTIALS_DIR, `line-${accountId}-token.txt`);
}

function directoryFilePath(accountId) {
  return path.join(AGENTS_DIR, accountId, 'knowledge', 'member_directory.md');
}

function loadMap(accountId) {
  try {
    return JSON.parse(fs.readFileSync(mapFilePath(accountId), 'utf8'));
  } catch (e) {
    return {};
  }
}

function saveMap(accountId, map) {
  try {
    fs.mkdirSync(STATE_DIR, { recursive: true });
    fs.writeFileSync(mapFilePath(accountId), JSON.stringify(map, null, 2));
  } catch (e) { /* silent */ }
}

// 解析 member_directory.md 的 markdown table 行：| 姓名 | 專業 | 電話 | 合作對象 |
// 沒有這份檔案的 agent（例如 jiaolian_thoughts）就直接回傳空陣列，guessMember 自然回 unmatched，不報錯
function loadDirectoryEntries(accountId) {
  try {
    const text = fs.readFileSync(directoryFilePath(accountId), 'utf8');
    const lines = text.split('\n');
    const entries = [];
    for (const line of lines) {
      const m = line.match(/^\|\s*([^|]+?)\s*\|\s*([^|]+?)\s*\|\s*(09\d{8})\s*\|\s*([^|]+?)\s*\|$/);
      if (m) {
        entries.push({ name: m[1].trim(), profession: m[2].trim(), phone: m[3].trim(), target: m[4].trim() });
      }
    }
    return entries;
  } catch (e) {
    return [];
  }
}

function guessMember(accountId, displayName, statusMessage) {
  const haystack = `${displayName || ''} ${statusMessage || ''}`;
  const entries = loadDirectoryEntries(accountId);
  if (entries.length === 0) {
    return { guessedMember: null, confidence: 'no_directory' };
  }

  // 1. 完整姓名命中（最可信）
  for (const e of entries) {
    if (e.name.length >= 2 && haystack.includes(e.name)) {
      return { guessedMember: `${e.name}（${e.profession}）`, confidence: 'high_name_match' };
    }
  }
  // 2. 名字（去掉姓氏首字）命中——LINE暱稱常只打名不打姓，例如「柯朝陽」暱稱裡只有「朝陽」
  for (const e of entries) {
    const givenName = e.name.slice(1);
    if (givenName.length >= 2 && haystack.includes(givenName)) {
      return { guessedMember: `疑似${e.name}（${e.profession}，僅名字「${givenName}」命中，姓氏未確認）`, confidence: 'medium_given_name_match' };
    }
  }
  // 3. 專業類別詞命中（最弱訊號）
  for (const e of entries) {
    if (e.profession.length >= 2 && haystack.includes(e.profession)) {
      return { guessedMember: `疑似${e.name}（${e.profession}，僅專業關鍵字命中）`, confidence: 'low_profession_match' };
    }
  }
  return { guessedMember: null, confidence: 'unmatched' };
}

function fetchLineProfile(userId, token) {
  return new Promise((resolve) => {
    const req = https.request({
      hostname: 'api.line.me',
      path: `/v2/bot/profile/${userId}`,
      method: 'GET',
      headers: { Authorization: `Bearer ${token}` },
    }, (res) => {
      let body = '';
      res.on('data', (chunk) => { body += chunk; });
      res.on('end', () => {
        try {
          if (res.statusCode === 200) resolve(JSON.parse(body));
          else resolve(null);
        } catch (e) { resolve(null); }
      });
    });
    req.on('error', () => resolve(null));
    req.end();
  });
}

// 從 sessionKey（格式 agent:<accountId>:line:direct:<userId> 或類似）解析出 accountId 與 LINE direct 判定
// 泛化重點：不再寫死 bni_tainan，任何 agent:<id> 的 LINE 私訊都適用
function parseLineDirectSession(event, ctx) {
  const sessionKey = String(event.sessionKey ?? ctx.sessionKey ?? '');
  if (!sessionKey.includes('line') || !sessionKey.includes('direct')) return null;
  const parts = sessionKey.split(':');
  // 預期格式：agent:<accountId>:line:direct:<userId>（跟既有bni_tainan session key一致）
  const agentIdx = parts.indexOf('agent');
  const accountId = agentIdx >= 0 && parts[agentIdx + 1] ? parts[agentIdx + 1] : null;
  if (!accountId) return null;
  return { accountId, sessionKey };
}

function extractUserId(event, ctx) {
  const raw = event.from ?? event.senderId ?? ctx.from ?? ctx.senderId ?? '';
  let id = String(raw);
  if (id.startsWith('line:')) id = id.slice('line:'.length);
  if (!id) {
    const sessionKey = String(event.sessionKey ?? ctx.sessionKey ?? '');
    const parts = sessionKey.split(':');
    id = parts[parts.length - 1] || '';
  }
  // 統一轉小寫存 key（跟 sessionKey 格式對齊），呼叫 LINE API 前另外轉大寫 U 開頭
  return id.toLowerCase(); // e.g. u895a0ad8e49d75f8303dc3d067282dc0
}

const handler = async (event) => {
  if (!event || typeof event !== 'object') return;
  if (event.type !== 'message' || event.action !== 'received') return;

  const ctx = event.context ?? {};
  const parsed = parseLineDirectSession(event, ctx);
  if (!parsed) return;
  const { accountId } = parsed;

  const userIdLower = extractUserId(event, ctx);
  if (!userIdLower) return;

  const map = loadMap(accountId);
  if (map[userIdLower]) return; // 已記錄過，不重複查

  let token;
  try {
    token = fs.readFileSync(tokenFilePath(accountId), 'utf8').trim();
  } catch (e) { return; }

  const userIdForApi = 'U' + userIdLower.replace(/^u/i, '');
  const profile = await fetchLineProfile(userIdForApi, token);
  if (!profile) return;

  const { guessedMember, confidence } = guessMember(accountId, profile.displayName, profile.statusMessage);

  map[userIdLower] = {
    userId: userIdLower,
    displayName: profile.displayName || '',
    statusMessage: profile.statusMessage || '',
    guessedMember,
    confidence,
    firstSeenAt: new Date().toISOString(),
  };
  saveMap(accountId, map);
};

module.exports = handler;
module.exports.default = handler;

