"use strict";

// OpenClaw Hook：line-user-memory
// 用途：public LINE agent（bni_tainan/jiaolian_thoughts）的訪客個人化記憶。
//       agent本身沒有write/exec工具（教練指示鎖死系統層權限），改由這支hook在
//       伺服器端（Node.js，不受LLM對話內容影響）幫每位用戶維護專屬筆記檔，
//       讓對話能「記得」這個人說過什麼——不用讓agent自己碰任何寫檔案工具。
// 事件：message:preprocessed（照 knowledge-search-inject/namecard-inbound 模板）
// 軍師建立 2026-07-26（教練：鎖權限不能連個人化服務都擋掉，要像VPS版小龍蝦一樣）

const fs = require('fs');
const path = require('path');

const HOME = process.env.HOME;
const AGENTS_DIR = path.join(HOME, '.openclaw', 'agents');
const COACH_LINE_ID = 'u895a0ad8e49d75f8303dc3d067282dc0'; // 統一小寫比對
const MAX_INJECT_CHARS = 3000;
const MAX_FILE_BYTES = 200000; // 單一用戶檔案上限約200KB，超過就不再注入避免token暴衝(仍持續append)

function extractText(event) {
  const c = (event && event.context) || {};
  const cands = [
    event.text,
    c.text, c.content, c.prompt, c.input, c.transcript, c.userText, c.body, c.userMessage,
    (c.message && (typeof c.message === 'string' ? c.message : (c.message.text || c.message.content))),
  ];
  const pickLast = (arr) => {
    if (Array.isArray(arr) && arr.length) {
      const last = arr[arr.length - 1];
      if (typeof last === 'string') return last;
      if (last && typeof last === 'object') return last.text || last.content || '';
    }
    return '';
  };
  cands.push(pickLast(event.messages));
  cands.push(pickLast(c.messages));
  for (const v of cands) if (typeof v === 'string' && v.trim()) return v;
  return '';
}

function parseSession(event, ctx) {
  const sessionKey = String(event.sessionKey ?? ctx.sessionKey ?? '');
  if (!sessionKey.includes('line')) return null;
  const parts = sessionKey.split(':');
  const agentIdx = parts.indexOf('agent');
  const accountId = agentIdx >= 0 && parts[agentIdx + 1] ? parts[agentIdx + 1] : null;
  if (!accountId) return null;

  let userId = String(event.from ?? event.senderId ?? ctx.from ?? ctx.senderId ?? '');
  if (userId.startsWith('line:')) userId = userId.slice('line:'.length);
  if (!userId) userId = parts[parts.length - 1] || '';
  userId = userId.toLowerCase();
  if (!userId) return null;

  return { accountId, userId };
}

function clientFilePath(accountId, userId) {
  const dir = path.join(AGENTS_DIR, accountId, 'clients');
  return { dir, file: path.join(dir, `${userId}.md`) };
}

const handler = async (event) => {
  if (!event || typeof event !== 'object') return;
  if (event.type !== 'message' || event.action !== 'preprocessed') return;
  if (!event.context || typeof event.context !== 'object') return;

  const ctx = event.context;
  const parsed = parseSession(event, ctx);
  if (!parsed) return;
  const { accountId, userId } = parsed;

  if (userId === COACH_LINE_ID) return; // 教練本人不套用這套，他有自己的memory系統

  const text = extractText(event);
  if (!text) return;

  const { dir, file } = clientFilePath(accountId, userId);

  // 1. 讀取既有紀錄，取尾端一段注入context（讓agent「記得」這個人）
  try {
    if (fs.existsSync(file)) {
      const existing = fs.readFileSync(file, 'utf8');
      const tail = existing.length > MAX_INJECT_CHARS
        ? existing.slice(existing.length - MAX_INJECT_CHARS)
        : existing;
      if (tail.trim()) {
        if (!ctx.inject) ctx.inject = [];
        if (Array.isArray(ctx.inject)) {
          ctx.inject.push({
            role: 'system',
            content: '📓 這位用戶過去的對話紀錄（自動累積，可參考來提供個人化服務，不確定的部分不要假裝很熟）：\n\n' + tail.trim(),
          });
        }
      }
    }
  } catch (e) { /* 讀取失敗不影響對話，靜默跳過 */ }

  // 2. 把這一則訊息append進該用戶專屬檔案（伺服器端寫入，agent不經手）
  try {
    fs.mkdirSync(dir, { recursive: true });
    let currentSize = 0;
    try { currentSize = fs.statSync(file).size; } catch (e) { /* 檔案不存在 */ }
    if (currentSize < MAX_FILE_BYTES) {
      const ts = new Date().toLocaleString('zh-TW', { timeZone: 'Asia/Taipei', hour12: false });
      fs.appendFileSync(file, `- [${ts}] ${text.replace(/\n/g, ' ')}\n`);
    }
  } catch (e) { /* 寫入失敗不影響對話，靜默跳過 */ }
};

module.exports = handler;
module.exports.default = handler;

"use strict";

// OpenClaw Hook：line-user-memory
// 用途：public LINE agent（bni_tainan/jiaolian_thoughts）的訪客個人化記憶。
//       agent本身沒有write/exec工具（教練指示鎖死系統層權限），改由這支hook在
//       伺服器端（Node.js，不受LLM對話內容影響）幫每位用戶維護專屬筆記檔，
//       讓對話能「記得」這個人說過什麼——不用讓agent自己碰任何寫檔案工具。
// 事件：message:preprocessed（照 knowledge-search-inject/namecard-inbound 模板）
// 軍師建立 2026-07-26（教練：鎖權限不能連個人化服務都擋掉，要像VPS版小龍蝦一樣）

const fs = require('fs');
const path = require('path');

const HOME = process.env.HOME;
const AGENTS_DIR = path.join(HOME, '.openclaw', 'agents');
const COACH_LINE_IDS = new Set([
  'u895a0ad8e49d75f8303dc3d067282dc0', // 教練主帳號「吳大樹」
  'u168903487f0ba2b666ddc62b854de351', // 教練第二帳號「贏家思路」
]); // 統一小寫比對
const MAX_INJECT_CHARS = 3000;
const MAX_FILE_BYTES = 200000; // 單一用戶檔案上限約200KB，超過就不再注入避免token暴衝(仍持續append)

function extractText(event) {
  const c = (event && event.context) || {};
  const cands = [
    event.text,
    c.text, c.content, c.prompt, c.input, c.transcript, c.userText, c.body, c.userMessage,
    (c.message && (typeof c.message === 'string' ? c.message : (c.message.text || c.message.content))),
  ];
  const pickLast = (arr) => {
    if (Array.isArray(arr) && arr.length) {
      const last = arr[arr.length - 1];
      if (typeof last === 'string') return last;
      if (last && typeof last === 'object') return last.text || last.content || '';
    }
    return '';
  };
  cands.push(pickLast(event.messages));
  cands.push(pickLast(c.messages));
  for (const v of cands) if (typeof v === 'string' && v.trim()) return v;
  return '';
}

function parseSession(event, ctx) {
  const sessionKey = String(event.sessionKey ?? ctx.sessionKey ?? '');
  if (!sessionKey.includes('line')) return null;
  const parts = sessionKey.split(':');
  const agentIdx = parts.indexOf('agent');
  const accountId = agentIdx >= 0 && parts[agentIdx + 1] ? parts[agentIdx + 1] : null;
  if (!accountId) return null;

  let userId = String(event.from ?? event.senderId ?? ctx.from ?? ctx.senderId ?? '');
  if (userId.startsWith('line:')) userId = userId.slice('line:'.length);
  if (!userId) userId = parts[parts.length - 1] || '';
  userId = userId.toLowerCase();
  if (!userId) return null;

  return { accountId, userId };
}

function clientFilePath(accountId, userId) {
  const dir = path.join(AGENTS_DIR, accountId, 'clients');
  return { dir, file: path.join(dir, `${userId}.md`) };
}

const handler = async (event) => {
  if (!event || typeof event !== 'object') return;
  if (event.type !== 'message' || event.action !== 'preprocessed') return;
  if (!event.context || typeof event.context !== 'object') return;

  const ctx = event.context;
  const parsed = parseSession(event, ctx);
  if (!parsed) return;
  const { accountId, userId } = parsed;

  if (userId === COACH_LINE_ID) return; // 教練本人不套用這套，他有自己的memory系統

  const text = extractText(event);
  if (!text) return;

  const { dir, file } = clientFilePath(accountId, userId);

  // 1. 讀取既有紀錄，取尾端一段注入context（讓agent「記得」這個人）
  try {
    if (fs.existsSync(file)) {
      const existing = fs.readFileSync(file, 'utf8');
      const tail = existing.length > MAX_INJECT_CHARS
        ? existing.slice(existing.length - MAX_INJECT_CHARS)
        : existing;
      if (tail.trim()) {
        if (!ctx.inject) ctx.inject = [];
        if (Array.isArray(ctx.inject)) {
          ctx.inject.push({
            role: 'system',
            content: '📓 這位用戶過去的對話紀錄（自動累積，可參考來提供個人化服務，不確定的部分不要假裝很熟）：\n\n' + tail.trim(),
          });
        }
      }
    }
  } catch (e) { /* 讀取失敗不影響對話，靜默跳過 */ }

  // 2. 把這一則訊息append進該用戶專屬檔案（伺服器端寫入，agent不經手）
  try {
    fs.mkdirSync(dir, { recursive: true });
    let currentSize = 0;
    try { currentSize = fs.statSync(file).size; } catch (e) { /* 檔案不存在 */ }
    if (currentSize < MAX_FILE_BYTES) {
      const ts = new Date().toLocaleString('zh-TW', { timeZone: 'Asia/Taipei', hour12: false });
      fs.appendFileSync(file, `- [${ts}] ${text.replace(/\n/g, ' ')}\n`);
    }
  } catch (e) { /* 寫入失敗不影響對話，靜默跳過 */ }
};

module.exports = handler;
module.exports.default = handler;

